//! Remediation, reviews and emergency changes (Genesis Mesh 1.4.0): the
//! shared conformance suite `remediation`, generated by the Python reference
//! (genesismesh/conformance/generate_vectors.py) and copied unchanged, and the
//! remediation records this crate signs.

use std::collections::BTreeSet;

use base64::{engine::general_purpose::STANDARD, Engine as _};
use chrono::{DateTime, Utc};
use genesis_mesh_sdk::{
    canonical::{out_of_band_canonical, out_of_band_digest, policy_canonical, policy_digest},
    json, public_key_from_seed,
    remediation::{
        admin_approval_valid, check_remediation, due_after_denial, due_after_waiver, next_state,
        policy_section_issues, remediation_plan, review_approval_problem, review_holder_problem,
        steps_problem, ChangeFacts, RemediationDefaults, ReviewHolders,
    },
    verify::{
        parse_export_lines, verify_evidence_events, verify_out_of_band_record,
        VerifyEvidenceOptions,
    },
    ExecutionRecorder, GenesisMeshError, RemediationInput, RemediationSteps, RemediationSubject,
    Value,
};

fn suite() -> Value {
    serde_json::from_str(include_str!("fixtures/remediation.json")).unwrap()
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect()
}

fn at(value: &str) -> DateTime<Utc> {
    value.parse().unwrap()
}

fn maybe_at(value: &Value) -> Option<DateTime<Utc>> {
    value.as_str().map(at)
}

/// The reference runner's time form: UTC with `Z`.
fn iso(value: DateTime<Utc>) -> String {
    value.to_rfc3339_opts(chrono::SecondsFormat::AutoSi, true)
}

const COUNTS: [&str; 6] = [
    "observations",
    "break_glass",
    "judgements",
    "quarantined",
    "remediations",
    "reviews",
];

fn run(v: &Value) -> Value {
    match v["kind"].as_str().unwrap() {
        "policy_canonical" => json!({
            "canonical": policy_canonical(&v["record"]).unwrap(),
            "digest": policy_digest(&v["record"]).unwrap(),
        }),
        "policy_validation" => {
            let codes: BTreeSet<&str> = policy_section_issues(&v["record"])
                .into_iter()
                .map(|(code, _)| code)
                .collect();
            json!({ "codes": codes })
        }
        "remediation_plan" => {
            let input = &v["input"];
            let defaults = RemediationDefaults {
                grace_seconds: input["defaults"]["grace_seconds"].as_i64().unwrap(),
                mode: input["defaults"]["mode"].as_str().unwrap().into(),
            };
            let facts = ChangeFacts {
                action: input["action"].as_str().unwrap().into(),
                version_id: input["version_id"].as_str().map(str::to_owned),
                rotatable: input["rotatable"].as_bool().unwrap(),
            };
            let plan = remediation_plan(
                input["verdict"].as_str().unwrap(),
                input["policies"].as_array().unwrap(),
                input["gate_evaluations"].as_array().unwrap(),
                &facts,
                &defaults,
            );
            json!({
                "mode": plan.mode, "steps": plan.steps, "fallback": plan.fallback,
                "grace_seconds": plan.grace_seconds, "source": plan.source,
                "remediation_due_at": iso(plan.due_at(at(input["judged_at"].as_str().unwrap()))),
            })
        }
        "due_time" => {
            let input = &v["input"];
            let grace = input["grace_seconds"].as_i64().unwrap();
            let due = match v["rule"].as_str().unwrap() {
                "review_denial" => due_after_denial(
                    maybe_at(&input["current_due"]),
                    at(input["decided_at"].as_str().unwrap()),
                    grace,
                ),
                _ => due_after_waiver(at(input["waived_until"].as_str().unwrap()), grace),
            };
            json!({ "remediation_due_at": iso(due) })
        }
        "transition" => match next_state(
            v["input"]["state"].as_str().unwrap(),
            v["input"]["event"].as_str().unwrap(),
        ) {
            Ok(state) => json!({ "state": state }),
            Err(refused) => json!({ "refused": refused.code }),
        },
        "canonical_form" => json!({
            "canonical": out_of_band_canonical(&v["record"]).unwrap(),
            "digest": out_of_band_digest(&v["record"]).unwrap(),
        }),
        "verify_record" => json!({
            "valid": verify_out_of_band_record(
                &v["record"],
                &[v["public_key"].as_str().unwrap().to_owned()]
            )
        }),
        "remediation_check" => json!({
            "code": check_remediation(&v["record"], Some(&v["key"])).map(|(code, _)| code)
        }),
        "steps_problem" => json!({
            "consistent": steps_problem(
                v["plan"]["mode"].as_str().unwrap(),
                v["plan"]["steps"].as_str().unwrap(),
                &v["record"],
            )
            .is_none()
        }),
        "admin_approval" => json!({ "valid": admin_approval_valid(&v["approval"]) }),
        "review_approval" => json!({
            "valid": review_approval_problem(&v["record"], &strings(&v["audiences"])).is_none()
        }),
        "review_holders" => {
            let input = &v["input"];
            let holders = ReviewHolders::of(input);
            json!({ "code": review_holder_problem(&holders).map(|(code, _)| code) })
        }
        "verify_export" => {
            let input = &v["input"];
            let events = parse_export_lines(input["lines"].as_str().unwrap()).unwrap();
            let options = VerifyEvidenceOptions {
                contiguous: input["contiguous"].as_bool().unwrap(),
                ..VerifyEvidenceOptions::new(
                    strings(&input["na_public_keys"]),
                    input["executor_keys"].as_array().unwrap().clone(),
                )
            };
            let result = verify_evidence_events(&events, &options);
            // Deduplicated and sorted, as the reference runner reports them.
            let found: BTreeSet<(i64, String)> = result
                .failures
                .iter()
                .map(|f| (f.store_sequence.unwrap_or(0), f.reason.clone()))
                .collect();
            let failures: Vec<Value> = found
                .into_iter()
                .map(|(seq, reason)| json!({"store_sequence": seq, "reason": reason}))
                .collect();
            let serialized = serde_json::to_value(&result).unwrap();
            let counts: serde_json::Map<String, Value> = COUNTS
                .iter()
                .filter_map(|k| Some((k.to_string(), serialized.get(*k)?.clone())))
                .collect();
            json!({"verified": result.verified, "failures": failures, "counts": counts})
        }
        other => panic!("unknown vector kind {other}"),
    }
}

#[test]
fn every_vector_gives_the_reference_outcome() {
    let suite = suite();
    assert_eq!(suite["suite"], "remediation");
    let vectors = suite["vectors"].as_array().unwrap();
    let mut failed = Vec::new();
    for v in vectors {
        let got = run(v);
        if got != v["expected"] {
            failed.push(format!(
                "{}: expected {}, got {got}",
                v["id"], v["expected"]
            ));
        }
    }
    assert!(failed.is_empty(), "{}", failed.join("\n"));
    assert_eq!(vectors.len(), 195);
}

fn vector(id: &str) -> Value {
    suite()["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == id)
        .unwrap_or_else(|| panic!("no vector {id}"))
        .clone()
}

#[test]
fn a_review_whose_approval_is_changed_does_not_verify() {
    let v = vector("review-approval-valid");
    let audiences = strings(&v["audiences"]);
    assert_eq!(review_approval_problem(&v["record"], &audiences), None);
    let mut extra = v["record"].clone();
    extra["approval"]["body"]["extra"] = json!("x");
    // The decider did not sign that body.
    assert!(review_approval_problem(&extra, &audiences)
        .unwrap()
        .contains("decider's signature does not verify"));
    let mut late = v["record"].clone();
    late["requested_at"] = json!("2026-01-01T00:20:00Z");
    assert!(review_approval_problem(&late, &audiences)
        .unwrap()
        .contains("requester's request was signed more than 300s"));
    let mut query = v["record"].clone();
    query["approval"]["query"] = json!({"x": ["1"]});
    assert!(review_approval_problem(&query, &audiences).is_some());
}

#[test]
fn the_holder_rule_takes_the_first_rule_that_matches() {
    let both = ReviewHolders {
        decided_by: "operator-1",
        decider_holder: "holder-1",
        requested_by: Some("operator-1"),
        requester_holder: Some("holder-1"),
        actor: Some("holder-1"),
        actor_holder: Some("holder-1"),
    };
    assert_eq!(
        review_holder_problem(&both).unwrap().0,
        "review_same_holder_as_requester"
    );
    let actor_named_like_holder = ReviewHolders {
        requested_by: None,
        requester_holder: None,
        actor_holder: None,
        ..both
    };
    assert_eq!(
        review_holder_problem(&actor_named_like_holder).unwrap().0,
        "review_same_holder_as_actor"
    );
    let no_actor = ReviewHolders {
        actor: None,
        ..actor_named_like_holder
    };
    assert_eq!(review_holder_problem(&no_actor), None);
}

// ── Policies: the 1.4.0 sections and the 1.3 digest ──────────────────────────

fn registry_vector(id: &str) -> Value {
    let suite: Value = serde_json::from_str(include_str!("fixtures/field_registry.json")).unwrap();
    suite["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == id)
        .unwrap()["record"]
        .clone()
}

#[test]
fn a_policy_keeps_its_digest_when_the_new_sections_are_null() {
    // The 1.3 policy and the guided one, with the digests the core computes.
    let plain = registry_vector("boundarypolicy-clean");
    let digest = policy_digest(&plain).unwrap();
    assert!(digest.starts_with("7921f8ac5dccd5cf"), "{digest}");
    let mut nulls = plain.clone();
    for section in ["remediation", "review_required", "emergency"] {
        nulls[section] = Value::Null;
    }
    assert_eq!(policy_digest(&nulls).unwrap(), digest);
    assert_eq!(
        policy_canonical(&nulls).unwrap(),
        policy_canonical(&plain).unwrap()
    );
    let guided = registry_vector("boundarypolicy-guided");
    assert!(policy_digest(&guided)
        .unwrap()
        .starts_with("768bdcfaadfbd0bd"));
    // A section that is present is signed, even when empty.
    let mut empty = plain;
    empty["remediation"] = json!({});
    assert_ne!(policy_digest(&empty).unwrap(), digest);
}

#[test]
fn a_decision_under_a_policy_received_with_null_sections_verifies() {
    use genesis_mesh_sdk::verify::{verify_boundary_decision, VerifyDecisionOptions};
    let vectors: Value =
        serde_json::from_str(include_str!("fixtures/python-vectors.json")).unwrap();
    let decision = &vectors["allowed"]["decision"];
    let policy = &vectors["policy"];
    let mut nulls = policy.clone();
    for section in ["remediation", "review_required", "emergency"] {
        nulls[section] = Value::Null;
    }
    for expected in [policy, &nulls] {
        let options = VerifyDecisionOptions {
            operator_public_keys: vec![vectors["na_public_key"].as_str().unwrap().to_owned()],
            now: decision["decision_made_at"].as_str().map(at),
            expected_policies: Some(vec![expected.clone()]),
            ..VerifyDecisionOptions::default()
        };
        let verification = verify_boundary_decision(decision, &options);
        assert_eq!(verification.reason, "authorized", "{expected}");
    }
}

#[test]
fn policy_sections_are_checked_as_the_na_checks_them() {
    let mut policy = registry_vector("boundarypolicy-clean");
    policy["remediation"] = json!({"*": {"mode": "cancel", "grace_seconds": 3600}});
    assert!(policy_section_issues(&policy).is_empty());
    policy["remediation"] = json!({"*": {"mode": "rollback", "grace_seconds": 3600}});
    assert_eq!(policy_section_issues(&policy)[0].0, "invalid_remediation");
    policy["remediation"] = json!({"*": {"mode": "cancel", "grace_seconds": 2_592_001}});
    assert_eq!(policy_section_issues(&policy)[0].0, "invalid_remediation");
    policy["remediation"] = Value::Null;
    policy["review_required"] = json!(false);
    assert_eq!(policy_section_issues(&policy)[0].0, "invalid_remediation");
    policy["review_required"] = json!(true);
    policy["emergency"] = json!({"stands_for": "x", "justification_parameter": "why"});
    assert_eq!(policy_section_issues(&policy)[0].0, "invalid_emergency");
}

// ── Remediation records this crate signs ─────────────────────────────────────

fn seed(byte: u8) -> String {
    STANDARD.encode([byte; 32])
}

fn executor() -> ExecutionRecorder {
    ExecutionRecorder::new("secrets-controller", "ctrl-1", &seed(21)).unwrap()
}

fn key() -> Value {
    json!({"key_id": "ctrl-1", "public_key": public_key_from_seed(&seed(21)).unwrap(),
           "executor_sovereign_id": "secrets-controller", "role": "executor"})
}

fn subject() -> RemediationSubject {
    RemediationSubject {
        subject_kind: "judgement".into(),
        subject_id: "judgement-1".into(),
        change_kind: "observation".into(),
        change_id: "observation-1".into(),
        resource_id: "kv:vendor-acme/api-key".into(),
    }
}

fn rotated(version: &str, disabled: &str) -> RemediationSteps {
    RemediationSteps::RotateForwardThenDisable {
        rotation_evidence_id: "evidence-9".into(),
        version_id: version.into(),
        disabled_version_id: disabled.into(),
    }
}

fn refusal(err: GenesisMeshError) -> String {
    assert!(
        matches!(err, GenesisMeshError::OutOfBandRecord { .. }),
        "{err}"
    );
    err.code().to_owned()
}

#[test]
fn a_forward_rotation_is_signed_in_the_reference_form_and_admitted() {
    let record = executor()
        .sign_remediation(RemediationInput {
            remediated_at: Some(at("2026-11-02T10:20:00Z")),
            ..RemediationInput::new(subject(), rotated("v9", "v8"))
        })
        .unwrap();
    assert_eq!(record["outcome"], "cancelled");
    assert_eq!(record["steps"], "rotate_forward_then_disable");
    assert_eq!(record["rotation_evidence_id"], "evidence-9");
    assert_eq!(record["remediated_at"], "2026-11-02T10:20:00Z");
    assert!(record.get("detail").is_none());
    assert_eq!(check_remediation(&record, Some(&key())), None);
    let keys = [key()["public_key"].as_str().unwrap().to_owned()];
    assert!(verify_out_of_band_record(&record, &keys));
}

#[test]
fn every_kind_of_remediation_has_its_outcome_and_versions() {
    let recorder = executor();
    let alerted = recorder
        .sign_remediation(RemediationInput::new(subject(), RemediationSteps::Alerted))
        .unwrap();
    assert_eq!(
        (&alerted["outcome"], &alerted["steps"]),
        (&json!("alerted"), &json!("none"))
    );
    assert!(alerted.get("disabled_version_id").is_none());
    let deleted = recorder
        .sign_remediation(RemediationInput::new(
            subject(),
            RemediationSteps::Delete {
                disabled_version_id: Some("v8".into()),
            },
        ))
        .unwrap();
    assert_eq!(deleted["steps"], "delete");
    assert_eq!(deleted["disabled_version_id"], "v8");
    assert!(deleted.get("version_id").is_none());
    for record in [&alerted, &deleted] {
        assert_eq!(check_remediation(record, Some(&key())), None);
    }
    // The plan they carry out.
    assert!(steps_problem("cancel", "disable", &deleted).is_none());
    assert!(steps_problem("cancel", "disable", &alerted).is_some());
    assert!(steps_problem("alert_only", "none", &alerted).is_none());
}

#[test]
fn a_remediation_the_na_would_refuse_is_not_signed() {
    let recorder = executor();
    let refuse = |input: RemediationInput| refusal(recorder.sign_remediation(input).unwrap_err());
    assert_eq!(
        refuse(RemediationInput::new(subject(), rotated("v8", "v8"))),
        "remediation_malformed"
    );
    let unknown_kind = RemediationSubject {
        change_kind: "console".into(),
        ..subject()
    };
    assert_eq!(
        refuse(RemediationInput::new(
            unknown_kind,
            RemediationSteps::Alerted
        )),
        "remediation_malformed"
    );
    let empty = RemediationSubject {
        subject_id: String::new(),
        ..subject()
    };
    assert_eq!(
        refuse(RemediationInput::new(empty, RemediationSteps::Alerted)),
        "remediation_malformed"
    );
    let long_detail = RemediationInput {
        detail: Some("x".repeat(1025)),
        ..RemediationInput::new(subject(), RemediationSteps::Alerted)
    };
    assert_eq!(refuse(long_detail), "remediation_malformed");
    let pem = RemediationSteps::Disable {
        disabled_version_id: Some("-----BEGIN PRIVATE KEY-----".into()),
    };
    assert_eq!(
        refuse(RemediationInput::new(subject(), pem)),
        "remediation_secret_material"
    );
    let token_detail = RemediationInput {
        detail: Some(format!(
            "eyJ{}.{}.{}",
            "a".repeat(10),
            "b".repeat(10),
            "c".repeat(10)
        )),
        ..RemediationInput::new(subject(), RemediationSteps::Alerted)
    };
    assert_eq!(refuse(token_detail), "remediation_secret_material");
}

#[test]
fn check_remediation_names_the_refusal_the_na_answers() {
    let record = executor()
        .sign_remediation(RemediationInput::new(subject(), rotated("v9", "v8")))
        .unwrap();
    let with = |changes: Value| {
        let mut k = key();
        for (name, value) in changes.as_object().unwrap() {
            k[name] = value.clone();
        }
        check_remediation(&record, Some(&k)).map(|(code, _)| code)
    };
    assert_eq!(
        with(json!({"retired": true})),
        Some("remediation_key_retired")
    );
    assert_eq!(
        with(json!({"role": "observer"})),
        Some("remediation_out_of_scope")
    );
    assert_eq!(
        with(json!({"resource_prefix": "kv:other/"})),
        Some("remediation_out_of_scope")
    );
    assert_eq!(with(json!({"resource_prefix": "kv:vendor-acme/"})), None);
    assert_eq!(
        with(json!({"executor_sovereign_id": "other"})),
        Some("remediation_unknown_key")
    );
    assert_eq!(
        check_remediation(&record, None).map(|(code, _)| code),
        Some("remediation_unknown_key")
    );
    let mut unsigned = record.clone();
    unsigned.as_object_mut().unwrap().remove("signature");
    assert_eq!(
        check_remediation(&unsigned, Some(&key())).map(|(code, _)| code),
        Some("remediation_invalid_signature")
    );
    let mut extra = record.clone();
    extra["x_added_field"] = json!(1);
    assert_eq!(
        check_remediation(&extra, Some(&key())).map(|(code, _)| code),
        Some("remediation_malformed")
    );
    let mut inconsistent = record;
    inconsistent["outcome"] = json!("alerted");
    assert_eq!(
        check_remediation(&inconsistent, Some(&key())).map(|(code, _)| code),
        Some("remediation_malformed")
    );
}

#[test]
fn a_remediation_subject_is_read_from_the_due_queue() {
    let state = json!({"subject_kind": "judgement", "subject_id": "judgement-1",
                       "change_kind": "observation", "change_id": "observation-1",
                       "resource_id": "kv:vendor-acme/api-key", "state": "remediation_due"});
    assert_eq!(RemediationSubject::from_state(&state), Some(subject()));
    let mut decision = state;
    decision["change_id"] = Value::Null;
    assert_eq!(RemediationSubject::from_state(&decision), None);
}
